<?php namespace App\Services; use App\Models\TipoDocumento; use Illuminate\Support\Facades\DB; class DocumentNumberService { public function siguiente(TipoDocumento $tipo, ?string $prefijo=null): array { return DB::transaction(function() use($tipo,$prefijo){ $tipo=TipoDocumento::whereKey($tipo->id)->lockForUpdate()->firstOrFail(); $prefijo=strtoupper($prefijo ?: $tipo->prefijo_default ?: $tipo->codigo); $fila=DB::table('documento_consecutivos')->where(['tipo_documento_id'=>$tipo->id,'prefijo'=>$prefijo])->lockForUpdate()->first(); if(!$fila){DB::table('documento_consecutivos')->insert(['tipo_documento_id'=>$tipo->id,'prefijo'=>$prefijo,'siguiente_numero'=>2,'created_at'=>now(),'updated_at'=>now()]);$n=1;}else{$n=$fila->siguiente_numero;DB::table('documento_consecutivos')->where('id',$fila->id)->update(['siguiente_numero'=>$n+1,'updated_at'=>now()]);} return ['prefijo'=>$prefijo,'consecutivo'=>$n,'numero'=>$prefijo.'-'.str_pad($n,6,'0',STR_PAD_LEFT)]; }); } }
